import React, { useRef, useEffect, useState } from "react";
import { Alert, Box, Button, Divider, Typography, IconButton, Tooltip, CircularProgress } from "@mui/material";
import FormField from "../FormField/FormField";
import RichTextEditor from "../RichTextEditor/RichTextEditor";
import Swal from "sweetalert2";
import PageHeader from "../PageHeader/PageHeader";
import CloseIcon from "@mui/icons-material/Close";
import FileDropZone from "../FileDropZone/FileDropZone";
import StickyNote2Icon from "@mui/icons-material/StickyNote2";
import { Stepper, Step, StepLabel } from "@mui/material";
import { toast } from "../../Utilities/toast";

import moment from "moment-timezone";
import { usePageTitle } from "../../Context/PageTitleContext";
import { useCustomTheme } from "../../Context/ThemeContext";
import { fetchCustomersService,fetchActiveCustomersService, fetchCustomerUsersService } from "../../Services/customerService";
import { DatePicker, DateTimePicker, renderTimeViewClock } from "@mui/x-date-pickers";
import { LocalizationProvider } from "@mui/x-date-pickers";
import { AdapterMoment } from "@mui/x-date-pickers/AdapterMoment";
import { fetchAgentsService } from "../../Services/agentService";
import { createTicketsService, calculateDueDateByDepartmentService } from "../../Services/ticketsService";
import { useLocation, useNavigate } from "react-router-dom";
import { useNamespace } from "../../Context/NamespaceContext";
import _, { capitalize } from "lodash";
import DrawerForm from "../DrawerForm/DrawerForm";
import { useAuth } from "../../Context/AuthContext";
import { fetchDepartmentsService } from "../../Services/departmentService";
import { useEntities } from "../../Context/EntitiesContext";
import { fetchCustomFormsByProvisionService } from "../../Services/formsServices";
import CustomFormDetail from "../CustomFormDetail/CustomFormDetail";
import { fetchAllServiceTypes } from "../../Services/serviceTypeService";
import { validateCustomFormFields as validateCustomFormsShared, isFieldVisible } from "../../Utilities/customFormValidation";
import { AlertService } from "../../Utilities/Template";
import { fetchTicketsSettingService } from "../../Services/ticketSettingService";
import { fetchTicketRoutingOptionsService } from "../../Services/routingTagsService";
import { filterProvisionsForCustomerUser, findCustomerUserById, getAccessibleSiteIdsForCustomerUser } from "../../Utilities/customerSiteScope";

const FORM_DEFAULTS = {
	customer: null, user: null, equipment: null,
	subject: "", description: "",
	ticket_notice: "all", priority: 2,
	attachment: null, files: [],
	staff_accountable: null, staff_assigned: null,
	sla: "", ticket_source: "web",
	department: null, service_type: null,
	due_date: null, email_id: null,
};

const CreateTicketForm = ({ formOpen, setFormOpen, setParentData, isExpanded, setIsExpanded, customer_id = null, user_id = null, prefill_assignee = null, equipment_id = null, initialSubject = "", initialDescription = "", emailId = null, initialFromEmail = "", initialFiles = [], prefill_subject = null, prefill_description = null }) => {
	const { user, userMode, userId, isAgent, hasPerms, userDepartments, hasPermsV2 } = useAuth();
	const { flexRow, flexCol } = useCustomTheme();
	const { entities, updateTickets } = useEntities();
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState(null);
	const [customerOptions, setCustomerOptions] = useState([]);
	const [userOptions, setUserOptions] = useState([]);
	const [equipmentOptions, setEquipmentOptions] = useState([]);
	const [agentOptions, setAgentOptions] = useState([]);
	const [agentOptionsAll, setAgentOptionsAll] = useState([]);
	const [departmentsOptions, setDepartmentsOptions] = useState([]);
	const [departmentsOptionsFiltered, setDepartmentsOptionsFiltered] = useState([]);
	const [departments, setDepartments] = useState([]);
	const [departmentsData, setDepartmentsData] = useState([]); // Store full department data with manager_id
	const [serviceManagerOptions, setServiceManagerOptions] = useState([]);
	const [serviceManagerOptionsAll, setServiceManagerOptionsAll] = useState([]);
	const [agentDeptMap, setAgentDeptMap] = useState(new Map());
	const [allUsers, setAllUsers] = useState([]);
	const customerSetByUserRef = useRef(false);
	const [allCustomers, setAllCustomers] = useState([]);
	const [alert, setAlert] = useState(null);
	const [formSubmitting, setFormSubmitting] = useState(false);
	const [formLoading, setFormLoading] = useState(false);
	const location = useLocation();
	// Add new state to store full service type data with departments
	const [serviceTypesData, setServiceTypesData] = useState([]);
	const [routingServiceTypesData, setRoutingServiceTypesData] = useState(null);
	const [routingTagInfo, setRoutingTagInfo] = useState(null);
	const [defaultServiceTypeId, setDefaultServiceTypeId] = useState(null);
	const [formData, setFormData] = useState({
		customer: null,
		user: null,
		equipment: null,
		subject: "",
		description: "",
		ticket_notice: "all",
		priority: 2,
		attachment: null,
		files: [],
		staff_accountable: null,
		staff_assigned: null,
		sla: "",
		ticket_source: "web",
		department: null,
		service_type: null,
		due_date: null,
		email_id: null,
	});
	const [customerPathID, setCustomerPathID] = useState(null);
	const [formErrors, setFormErrors] = useState({});
	const [disabledAll, setDisabledAll] = useState(true);
	const { getNamespace, nsp } = useNamespace();
	const initialFormDataRef = useRef();
	// Stores the user ID resolved from initialFromEmail — set after customer is applied and userOptions rebuild
	const pendingEmailUserIdRef = useRef(null);
	// ref so submit handler always sees latest emailId regardless of state batching order
	const emailIdRef = useRef(emailId);
	useEffect(() => { emailIdRef.current = emailId || null; }, [emailId]);
	const [defaultPriority, setDefaultPriority] = useState(null);
	const [isOrgWideTicketsEnabled, setIsOrgWideTicketsEnabled] = useState(false);
	const [isChildTicketVisibilityEnabled, setIsChildTicketVisibilityEnabled] = useState(false);
	const editorRef = useRef();
	const navigate = useNavigate();
	const textFieldRef = useRef(null);
	const [slaDueDate, setSlaDueDate] = useState(null);
	const [formTitle, setFormTitle] = useState({
		title: `Create New ${getNamespace("ticket", {
			capitalize: true,
			plural: false,
		})}`,
		subtitle: `Please fill out all the details to create a ${getNamespace("ticket", {
			capitalize: true,
			plural: false,
		})}`,
	});
	// Map priority string to numeric value
	const getPriorityValue = (priorityString) => {
		const priorityMap = {
			'Low': 1,
			'Normal': 2,
			'High': 3,
			'Emergency': 4
		};
		return priorityMap[priorityString] || 2; // Default to Normal (2) if not found
	};
	const [serviceTypes, setServiceTypes] = useState([]);
	const effectiveServiceTypesData = routingServiceTypesData || serviceTypesData;
	const canCreateAttachments = !isAgent || hasPermsV2("ticket_management.ticket_attachments.create", formData.department);
	const isActiveCustomerUser = (user) => {
		const status = user?.status;
		return status === true || status === 1 || status === "1";
	};

	const normalizeEmailSubjectForPrefill = (subject) => {
		const raw = String(subject || "").trim();
		if (!raw) return "";

		// Strip common client prefixes like Re:, Fwd:, etc.
		let out = raw.replace(/^(?:\s*(?:re|fw|fwd)\s*:\s*)+/i, "").trim();

		// Strip only the first leading [...] bracket chunk (and an optional "-" separator)
		// from the start of the subject. Single pass — any additional brackets are intentionally
		// kept so the user can see the full original context (e.g. "[Ticket #123]") in the prefill.
		const m = out.match(/^\[[^\]]*\]\s*(?:-\s*)?(.*)$/);
		if (m && String(m[1] || "").trim()) {
			out = String(m[1]).trim();
		}

		return out;
	};

	const sanitizeEmailBodyForPrefill = (htmlOrText) => {
		// Inline images embedded via `cid:` in the source HTML are promoted to ticket
		// attachments by the backend, but the `<img src="cid:...">` tag itself would render
		// as a broken image (and worse, its alt text would leak into the description text
		// extracted by DOMParser below). Strip those tags first.
		const cidStripped = String(htmlOrText || "").replace(
			/<img\b[^>]*\bsrc\s*=\s*["']cid:[^"']*["'][^>]*>/gi,
			""
		);
		const raw = cidStripped.trim();
		if (!raw) return "";

		// Convert HTML -> plain text for robust signature/quote trimming.
		// This intentionally trades exact HTML formatting for clean, relevant content.
		let text = raw;
		try {
			if (/[<>]/.test(raw)) {
				const doc = new DOMParser().parseFromString(raw, "text/html");
				text = (doc?.body?.innerText || "").trim();
			}
		} catch {
			// fall back to raw
		}

		text = String(text || "").replace(/\r\n/g, "\n").trim();
		if (!text) return "";

		// Cut common signature/disclaimer blocks even when they appear inline (same line as message).
		// We only cut if the marker occurs after some real content.
		const cutAtFirstMarker = (input) => {
			const patterns = [
				// Signature separators / disclaimers
				/--\s*/m,
				/__{2,}\s*/m,
				// Confidentiality / legal-disclaimer markers. Colon is optional — many
				// senders write "Confidentiality Notice The information ..." without one.
				/confidentiality\s+notice\b/i,
				/\bconfidential\s*:/i,
				/\bdisclaimer\s*:/i,
				/\blegal\s+notice\b/i,
				/this\s+e-?mail\s+communic/i,
				/this\s+(?:message|email|e-?mail)\s+(?:and\s+any\s+attachments|is\s+intended)/i,
				/sent\s+from\s+my\b/i,
				// Common sign-offs
				/thanks\s*&\s*regards/i,
				/thanks\s+and\s+regards/i,
				/\bthanks\b/i,
				/\bthank\s+you\b/i,
				/\bregards\b/i,
				/\bbest\b/i,
				/\bsincerely\b/i,
				// Reply/quote headers
				/-----\s*original\s+message\s*-----/i,
				/^\s*on\s.+wrote:\s*$/im,
				/^\s*from:\s/im,
				/^\s*sent:\s/im,
				/^\s*to:\s/im,
				/^\s*subject:\s/im,
				/\bwrote:\s*$/i,
			];

			let minIdx = null;
			for (const re of patterns) {
				re.lastIndex = 0;
				const m = re.exec(input);
				if (!m) continue;
				const idx = m.index;
				if (idx <= 0) continue;
				if (minIdx == null || idx < minIdx) minIdx = idx;
			}

			if (minIdx == null) return input;
			const before = input.slice(0, minIdx).trim();
			return before || input;
		};

		text = cutAtFirstMarker(text).replace(/\r\n/g, "\n").trim();
		if (!text) return "";

		const lines = text.split("\n").map((l) => l.replace(/\s+$/g, ""));

		const isSignatureOrQuoteStart = (line) => {
			const s = String(line || "").trim();
			if (!s) return false;

			// Common email reply separators / quote headers
			if (/^(-{2,}\s*)?original message(\s*-{2,})?$/i.test(s)) return true;
			if (/^from:\s/i.test(s)) return true;
			if (/^sent:\s/i.test(s)) return true;
			if (/^to:\s/i.test(s)) return true;
			if (/^subject:\s/i.test(s)) return true;
			if (/^on .+ wrote:\s*$/i.test(s)) return true;

			// Common signature delimiters
			if (/^--\s*$/.test(s)) return true;
			if (/^__+\s*$/.test(s)) return true;
			if (/^thanks\b/i.test(s)) return true;
			if (/^thank you\b/i.test(s)) return true;
			if (/^regards\b/i.test(s)) return true;
			if (/^best\b/i.test(s)) return true;
			if (/^sincerely\b/i.test(s)) return true;
			if (/^confidentiality\s+notice\b/i.test(s)) return true;
			if (/^confidential\s*:/i.test(s)) return true;
			if (/^disclaimer\s*:/i.test(s)) return true;
			if (/^legal\s+notice\b/i.test(s)) return true;
			if (/^this\s+e-?mail\s+communic/i.test(s)) return true;
			if (/^this\s+(?:message|email|e-?mail)\s+(?:and\s+any\s+attachments|is\s+intended)/i.test(s)) return true;
			if (/^sent from my\b/i.test(s)) return true;

			return false;
		};

		let cutIndex = -1;
		for (let i = 0; i < lines.length; i++) {
			if (isSignatureOrQuoteStart(lines[i])) {
				cutIndex = i;
				break;
			}
		}

		const kept = (cutIndex >= 0 ? lines.slice(0, cutIndex) : lines)
			.join("\n")
			.replace(/\n{3,}/g, "\n\n")
			// Drop trailing signature delimiter lines that may be left behind
			.replace(/\n\s*(?:--|__+)\s*$/g, "")
			// Drop dangling inline delimiter at the very end
			.replace(/\s*(?:--|__+)\s*$/g, "")
			.trim();

		// Convert plain text back to minimal HTML for RichTextEditor.
		const escaped = kept
			.replace(/&/g, "&amp;")
			.replace(/</g, "&lt;")
			.replace(/>/g, "&gt;");
		return escaped.replace(/\n/g, "<br/>");
	};

	// Reset form state every time the dialog opens so stale values from the previous session don't persist
	useEffect(() => {
		if (!formOpen) return;
		setFormData(FORM_DEFAULTS);
		pendingEmailUserIdRef.current = null;
	}, [formOpen]);

	// Prefill customer when customer_id is provided
	useEffect(() => {
		if (!formOpen) return;
		if (customer_id !== null && customer_id !== undefined) {
			const normalized = Number(customer_id);
			setFormData((prev) => ({ ...prev, customer: Number.isNaN(normalized) ? customer_id : normalized }));
		}
	}, [formOpen, customer_id]);

    // Prefill assignee when provided (e.g., from AgentDetails)
    useEffect(() => {
        if (!formOpen) return;
        if (prefill_assignee !== null && prefill_assignee !== undefined) {
            setFormData((prev) => ({ ...prev, staff_assigned: prefill_assignee }));
        }
    }, [formOpen, prefill_assignee]);

    // Prefill subject/description when provided (e.g., from registration request ticket)
    useEffect(() => {
        if (!formOpen) return;
        const updates = {};
        if (prefill_subject) updates.subject = prefill_subject;
        if (prefill_description) updates.description = prefill_description;
        if (Object.keys(updates).length > 0) {
            setFormData((prev) => ({ ...prev, ...updates }));
        }
    }, [formOpen, prefill_subject, prefill_description]);

	// Prefill user when user_id is provided and user options are available
	useEffect(() => {
		if (!formOpen) return;
		if (user_id === null || user_id === undefined) return;
		// Only prefill once options contain the user
		const normalized = Number(user_id);
		const hasInOptions = Array.isArray(userOptions)
			? userOptions.some((opt) => {
				if (opt && typeof opt === "object") {
					if (Array.isArray(opt.options)) {
						// grouped options
						return opt.options.some((o) => String(o.value) === String(user_id));
					}
					return String(opt.value) === String(user_id);
				}
				return false;
			})
			: false;
		if (hasInOptions) {
			setFormData((prev) => ({ ...prev, user: Number.isNaN(normalized) ? user_id : normalized }));
		}
	}, [formOpen, user_id, userOptions]);

	//Prefill provision equipment when equipment_id is provided
	// Wait for customer to be set and equipment options to be populated
	useEffect(() => {
		if (!formOpen) return;
		if (equipment_id === null || equipment_id === undefined) return;
		// Wait for customer to be set and equipment options to be populated
		if (!formData.customer || equipmentOptions.length === 0) return;

		// Check if the equipment exists in the available options
		const equipmentExists = equipmentOptions.some((opt) => String(opt.value) === String(equipment_id));
		if (equipmentExists) {
			const normalized = Number(equipment_id);
			setFormData((prev) => {
				// Only set if not already set to avoid unnecessary updates
				if (prev.equipment !== (Number.isNaN(normalized) ? equipment_id : normalized)) {
					return { ...prev, equipment: Number.isNaN(normalized) ? equipment_id : normalized };
				}
				return prev;
			});
		}
	}, [formOpen, equipment_id, formData.customer, equipmentOptions]);

	useEffect(() => {
		if (!formOpen) return;
		setFormData((prev) => ({
			...prev,
			...(initialSubject
				? {
						subject: emailId ? (normalizeEmailSubjectForPrefill(initialSubject) || "New Ticket") : initialSubject,
					}
				: {}),
			...(initialDescription
				? {
						description: emailId ? sanitizeEmailBodyForPrefill(initialDescription) : initialDescription,
					}
				: {}),
			email_id: emailId || null,
			...(emailId ? { ticket_source: "email" } : {}),
			...(initialFiles?.length ? { files: initialFiles } : {}),
		}));
	}, [formOpen, initialSubject, initialDescription, emailId, initialFiles]);

	// Auto-select customer when an email "from" address matches a known user.
	// User is set in a second step (inside the customer-change effect) once userOptions rebuild.
	useEffect(() => {
		if (!formOpen || !initialFromEmail || !allUsers.length) return;
		const match = allUsers.find(
			(u) => u.emails?.[0]?.address?.toLowerCase() === initialFromEmail.toLowerCase()
		);
		if (match) {
			pendingEmailUserIdRef.current = match.id;
			setFormData((prev) => ({ ...prev, customer: match.org_id }));
		}
	}, [formOpen, initialFromEmail, allUsers]);

	// Stepper/custom form state
	const [useStepper, setUseStepper] = useState(false);
	const [activeStep, setActiveStep] = useState(0);
	const [customFormsByProvision, setCustomFormsByProvision] = useState([]);
	const [customFormsForServiceType, setCustomFormsForServiceType] = useState([]);
	const [selectedChecklistId, setSelectedChecklistId] = useState(null);
	const [customFormValues, setCustomFormValues] = useState({});
	const [customFormErrors, setCustomFormErrors] = useState({});

    // Helper to resolve field label for error display for the selected form
    const getFieldLabelByKeyCF = (form, fieldKey) => {
        if (!form) return fieldKey;
        const fields = (form.fields || form.schema?.fields || []).map((f) => ({ ...f }));
        const hit = fields.find((f) => (f.name || f.id) === fieldKey);
        return hit?.label || fieldKey;
    };

	useEffect(() => {
		if (formOpen) {
			initialFormDataRef.current = _.cloneDeep(formData);
		}
		const pathnames = location.pathname.split("/").filter((x) => x);
		if (pathnames[0] === "customers" && !isNaN(pathnames[1])) {
			const id = parseInt(pathnames[1], 10);
			setCustomerPathID(id);
		}
	}, [formOpen]);

	useEffect(() => {
		const timer = setTimeout(() => {
			textFieldRef.current?.focus();
		}, 0);
		return () => clearTimeout(timer);
	}, [formOpen]);

	useEffect(() => {
		setFormTitle({
			title: `Create New ${getNamespace("ticket", {
				capitalize: true,
				plural: false,
			})}`,
			subtitle: `Please fill out all the details to create a ${getNamespace("ticket", {
				capitalize: true,
				plural: false,
			})}`,
		});

		fetchCustomers();
		fetchAgents();
		fetchDepartments();
}, [formOpen]);

// Whenever the form opens, refresh customer users to ensure latest options
useEffect(() => {
    if (formOpen) {
        fetchCustomerUsers();
    }
}, [formOpen]);

	useEffect(() => {
		if (formData.user && formData.user !== "") {
			if (!formData.customer || formData.customer === "") {
				const selectedCustomer = (allUsers || []).find((u) => u.id === formData.user)?.org_id;
				if (selectedCustomer) {
					customerSetByUserRef.current = true; //  don't clear user
					setFormData((prev) => ({ ...prev, customer: selectedCustomer }));
				}
			}
		}
	}, [formData.user, allUsers]);

	useEffect(() => {
		if (formData.customer && formData.customer !== "") {
			const selectedCus = allCustomers.find((cus) => String(cus.id) === String(formData.customer));
			const customerSites = selectedCus?.org_sites || [];
			const customerProvisions = selectedCus?.org_equipments || [];

			const baseOptions = (allUsers || []).map((customerUser) => ({
				org_id: customerUser.org_id,
				customer: customerUser.organization?.name,
				email: customerUser.emails?.[0]?.address,
				value: customerUser.id,
				label: customerUser.name,
				status: customerUser.status,
			}));

			let filteredUsers = baseOptions.filter((u) => u.org_id === formData.customer && u.status !== 0);

			// Staff flow: if a Unit is selected, only show customer users that can access that Unit's site.
			// This respects the child-ticket visibility setting (site descendants).
			if (isAgent && formData.equipment && !Boolean(isOrgWideTicketsEnabled)) {
				const selectedProvision = (customerProvisions || []).find(
					(p) => String(p?.id) === String(formData.equipment)
				);
				const provisionSiteId =
					selectedProvision?.site_id ??
					selectedProvision?.site?.id ??
					selectedProvision?.organization_site?.site_id ??
					null;

				if (provisionSiteId != null && provisionSiteId !== "") {
					const siteIdStr = String(provisionSiteId);
					filteredUsers = filteredUsers.filter((opt) => {
						const fullUser = findCustomerUserById(allUsers, opt.value);
						const accessibleIds = getAccessibleSiteIdsForCustomerUser(
							customerSites,
							fullUser,
							Boolean(isChildTicketVisibilityEnabled)
						);
						return accessibleIds.has(siteIdStr);
					});
				}
			}

			const nextOptions = filteredUsers.sort((a, b) => a.label.localeCompare(b.label));
			setUserOptions(nextOptions);

			// Second step of email-from prefill: set the matched user once options are ready.
			if (pendingEmailUserIdRef.current) {
				const pendingId = pendingEmailUserIdRef.current;
				if (nextOptions.some((opt) => String(opt.value) === String(pendingId))) {
					pendingEmailUserIdRef.current = null;
					customerSetByUserRef.current = true; // prevent the clear-user logic below from firing
					setFormData((prev) => ({ ...prev, user: pendingId }));
				}
			}

			// If current user is no longer valid after filtering, clear it (keep Unit selection).
			if (formData.user && !nextOptions.some((opt) => String(opt.value) === String(formData.user))) {
				setFormData((prev) => ({ ...prev, user: null }));
			}
			if (formData.user && formData.user !== "") {
				const selectedUserOrg = (allUsers || []).find((u) => u.id === formData.user)?.org_id;

			if (customerSetByUserRef.current) {
				// Customer was set BY user selection — never clear the user
				customerSetByUserRef.current = false;
				setDisabledAll(false);
			} else {
				// Customer was changed manually — clear user if it belongs to a different org
				if (selectedUserOrg !== formData.customer) {
				setFormData((prev) => ({ ...prev, user: null }));
				setDisabledAll(true);
				} else {
				setDisabledAll(false);
				}
			}
		} else {
			setDisabledAll(false);
			}
		} else {
			// Customer cleared — only reset user if it wasn't just set by user selection
			if (!customerSetByUserRef.current) {
			setFormData((prev) => ({ ...prev, user: null }));
			}
			customerSetByUserRef.current = false;

			const baseOptions = (allUsers || [])
				.filter(isActiveCustomerUser)
				.map((user) => ({
				org_id: user.org_id,
				customer: user.organization?.name,
				email: user.emails?.[0]?.address,
				value: user.id,
				label: user.name,
				status: user.status,
			}));
			setUserOptions(baseOptions.sort((a, b) => a.customer?.localeCompare(b.customer || "") || a.label.localeCompare(b.label)));
		}
	}, [
		formData.customer,
		formData.equipment,
		isAgent,
		isOrgWideTicketsEnabled,
		isChildTicketVisibilityEnabled,
		allUsers,
		allCustomers,
	]);

	useEffect(() => {
		if (!isAgent) {
			setFormData((prev) => ({ ...prev, user: user.id }));
		}
	}, [userOptions]);

	useEffect(() => {
		if (departmentsOptions.length > 0 && isAgent) {
			setFormData((prev) => ({ ...prev, department: departmentsOptions[0].value }));
		}
