										type="select"
										label="Priority"
										name="priority"
										value={formData.priority}
										error={formErrors.priority}
										onChange={handleFormChange}
										options={[
											{ label: "Low", value: 1 },
											{ label: "Normal", value: 2 },
											{ label: "High", value: 3 },
											{ label: "Emergency", value: 4 },
										]}
									/>


							<Divider flexItem />
							{isAgent && (
							<>
						<Box display="flex" alignItems="center" flexWrap="wrap">
							<Box display="flex" alignItems="center" width="100%">
								<Box width="200px" minWidth="200px">
									<Typography variant="body1" fontWeight={"bold"}>
										Due Date <span style={{ color: "red" }}>*</span>
									</Typography>
								</Box>

								<DateTimePicker
									value={formData.due_date}
									onChange={handleDateChange("due_date")}
									viewRenderers={{
										hours: renderTimeViewClock,
										minutes: renderTimeViewClock,
										seconds: renderTimeViewClock,
									}}
									slotProps={{
										textField: {
											size: "small",
											error: formErrors?.due_date,
										},
									}}
									sx={{
										flex: 1,
										minWidth: 130,
										width: "100%",
									}}
								/>
							</Box>
							{slaDueDate && !moment(formData.due_date).isSame(slaDueDate) && (
								<Box width="100%" display="flex" mt={0.5}>
									<Typography variant="body1" color="text.secondary" fontSize={"11px"}>
										<b>Note</b>: You have changed the due date and it is not as per SLA agreement.
									</Typography>
								</Box>
							)}
							</Box>
							<Divider flexItem />
							</>
							)}
							<FormField
								type="text"
								label="Subject"
								name="subject"
								value={formData.subject}
								error={formErrors.subject}
								onChange={handleFormChange}
								showRequired={true}
							/>
							<Box display="flex" alignItems="flex-start">
							<Box width="200px" minWidth="200px">
								<Typography fontWeight="bold">
									Description
								</Typography>
							</Box>
							<Box sx={{ width: "100%" }}>
								<RichTextEditor
									ref={editorRef}
									value={formData.description}
									onChange={handleEditorChange}
										placeholder={`Details on the reason(s) for opening the ${getNamespace(
											"ticket",
											{
												capitalize: true,
												plural: false,
											}
										)}...`}
									error={formErrors.description}
								/>
							</Box>
						</Box>
					{canCreateAttachments && (
						<Box display="flex" alignItems="flex-start">
							<Box width="200px" minWidth="200px">
									<Typography fontWeight="bold">Attachment</Typography>
								</Box>
								<Box sx={{ width: "100%", minWidth: 0, overflowX: "hidden" }}>
									<FileDropZone setParentData={setFormData} files={formData.files} truncateFileNames={true} />
									<Typography variant="body2" color="text.secondary" mt={0.5}>
										Note: Allowed file types: Image, PDF, Word, Excel, CSV, Eml, Easm, Mp4, Mov.
									</Typography>
								</Box>
							</Box>
							)}
						</>
					) : (
						<>{renderCustomFormsStep()}</>
					)}
						</>
					)}
				</DrawerForm>
			</LocalizationProvider>
		</>
	);
};

