	if (/<img\b/i.test(raw)) return true;
	if (/<a\b[^>]*href\s*=/i.test(raw)) return true;
	const text = raw
		.replace(/<style[\s\S]*?>[\s\S]*?<\/style>/gi, " ")
		.replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, " ")
