const isStaffManagerOrAdmin = async (staffId) => {
	const staffData = await resolveAccount(null, staffId, null);
	if (!staffData) return false;

	// Check if staff is admin or service manager at account level (Explicit Flags)
	if (staffData?.data?.isadmin || staffData?.data?.isservicemanager) return true;

	// Check department roles - verify by structured staff_type field
	const deptAccess = await models.staff_dept_access.findAll({
		where: { staff_id: staffId },
		include: [{ model: models.roles, as: 'role' }]
	});

	for (const access of deptAccess) {
		const staffType = access.role?.staff_type?.toLowerCase() || '';

		// Strict check based on staff_type metadata
		if (staffType === 'admin' || staffType === 'manager' || staffType === 'lead') {
