const getAppointmentVisibilityWhere = async (reqUser) => {
	let where = {};

	if (reqUser.staff_id) {
		const isManager = await isStaffManagerOrAdmin(reqUser.staff_id);
		const allowedDeptIds = await getAllowedDeptIds(reqUser.staff_id, 'appointment_management.appointment.view');
		const involvedTicketIds = await getStaffInvolvedTicketIds(reqUser.staff_id);

		const ticketInvolvementFilter =
			involvedTicketIds && involvedTicketIds.length > 0
				? { '$ticket.ticket_id$': { [Op.in]: involvedTicketIds } }
				: null;

		const deptFilter = {
			[Op.or]: [
				{ department_id: { [Op.in]: allowedDeptIds } },
				{ '$ticket.dept_id$': { [Op.in]: allowedDeptIds } }
			]
		};

		// Always allow staff to see their own unavailability slots,
		// even when those records are not tied to a department/ticket.
		const assignedToStaffFilter = { '$assigned_staff.staff_id$': reqUser.staff_id };
		const ownUnavailableFilter = {
			[Op.and]: [
				{ type: "unavailable" },
				{ '$assigned_staff.staff_id$': reqUser.staff_id }
			]
		};

		if (!allowedDeptIds || allowedDeptIds.length === 0) {
			// No department permissions:
			// - Managers/Admins: allow assigned + ticket-involved + own unavailability
			// - Engineers: allow assigned + own unavailability
			if (isManager) {
				return {
					[Op.or]: [
						assignedToStaffFilter,
						...(ticketInvolvementFilter ? [ticketInvolvementFilter] : []),
						ownUnavailableFilter
					]
				};
			}
			return {
				[Op.or]: [
					assignedToStaffFilter,
					ownUnavailableFilter
				]
			};
		}

		if (isManager) {
			// Managers see all in allowed departments + their own unavailable entries
			where = {
				[Op.or]: [
					deptFilter,
					...(ticketInvolvementFilter ? [ticketInvolvementFilter] : []),
					ownUnavailableFilter
				]
			};
		} else {
			// Service Engineers see ONLY their assigned appointments (any department) + their own unavailable slots.
			where = {
				[Op.or]: [
					assignedToStaffFilter,
					ownUnavailableFilter
				]
			};
		}
